"""Stop only this review's unadmitted wrapper after its documented 30-minute wait."""
import datetime,json,os,re,signal,subprocess,sys,time
from pathlib import Path
root=Path('/private/tmp/sf-fix279r4')
label=sys.argv[1]
queued=datetime.datetime.fromisoformat(sys.argv[2])
assert datetime.datetime.now(datetime.timezone.utc).timestamp()-queued.timestamp()>=1800
log=root/(label+'.log')
def admitted():
    return any(line.startswith(('hold ','R4_START ')) for line in log.read_text().splitlines()) or any((Path('/private/tmp/claude-501')/f'suite-hold-{pid}.held').exists() for pid in globals().get('all_pids',set()))
if admitted():
    print('Already admitted; no process interrupted.')
    sys.exit(0)
def pgrep(*args):
    result=subprocess.run(['pgrep',*args],capture_output=True,text=True)
    assert result.returncode in (0,1),(args,result.returncode,result.stderr)
    return {int(x) for x in result.stdout.split()}
# The unique scratch path and exact label constrain the match to our own wrapper.
pattern=re.escape(str(root/'run_pytest.py'))+' '+re.escape(label)+r'( |$)'
wrappers=pgrep('-f',pattern)
assert wrappers,('no matching task-owned wrapper',label)
stopped=set()
all_pids=set(wrappers)
try:
    # Freeze the matched parents so none can fork between census and shutdown.
    for pid in wrappers:
        try:os.kill(pid,signal.SIGSTOP);stopped.add(pid)
        except ProcessLookupError:pass
    while True:
        found=set()
        for pid in list(all_pids):found.update(pgrep('-P',str(pid)))
        new=found-all_pids
        if not new:break
        all_pids.update(new)
        for pid in new:
            try:os.kill(pid,signal.SIGSTOP);stopped.add(pid)
            except ProcessLookupError:pass
    if admitted():
        print('Admitted during the check; resumed without cancellation.')
        sys.exit(0)
    event=dict(label=label,utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),queued_utc=queued.isoformat(),pids=sorted(all_pids),purpose='stop this task-owned queued wrapper only; no pytest admitted')
    for pid in all_pids:
        try:os.kill(pid,signal.SIGTERM)
        except ProcessLookupError:pass
    (root/('cancelled-waiter-'+label+'.json')).write_text(json.dumps(event,indent=2))
    print(json.dumps(event))
finally:
    for pid in stopped:
        try:os.kill(pid,signal.SIGCONT)
        except ProcessLookupError:pass

